function setStatus(text:string,state:"ready"|"busy"|"error"){statusText.textContent=text;statusIndicator.className=`run-indicator${state==="ready"?"":` ${state}`}`;const scopeIndicator=must<HTMLElement>(".scope-run-state .run-indicator");scopeIndicator.className=`run-indicator${state==="ready"?"":` ${state}`}`;must<HTMLElement>("#scope-run-label").textContent=state==="ready"?"RUN":state==="busy"?"SOLVING":"BLOCKED";must<HTMLElement>("#engine-banner").dataset.engineState=state;if(state==="ready")statusText.dataset.testid="engine-ready";else delete statusText.dataset.testid;}
function detail(component:CircuitComponent){const part=partByType(component.type);return{ref:component.label?.text??`${part.prefix}${component.id.slice(1)}`,name:part.name,identity:component.mpn??"generic",note:part.note};}
