function sourceWaveformMarkup(component:CircuitComponent):string{if(component.type==="vsource_pulse"){const pulse=resolvedPulseWaveform(component);return`<div class="source-waveform" data-testid="pulse-waveform-fields"><span class="field-label sim-label">PULSE waveform</span><div class="source-waveform-grid">${([['v1','Initial V',pulse.v1],['v2','Pulsed V',pulse.v2],['delay','Delay',pulse.delay],['rise','Rise time',pulse.rise],['fall','Fall time',pulse.fall],['width','Pulse width',pulse.width],['period','Period',pulse.period]] as const).map(([field,label,value])=>`<label><span>${label}</span><input class="value-input source-waveform-field" data-source-param="${field}" value="${value}" inputmode="decimal"/></label>`).join("")}</div><p class="honesty-note">Times accept engineering suffixes. Width must not exceed period.</p></div>`;}if(component.type==="vsource_sine"){const sine=resolvedSineWaveform(component);return`<div class="source-waveform" data-testid="sine-waveform-fields"><span class="field-label sim-label">SINE waveform</span><div class="source-waveform-grid"><label><span>Offset V</span><input class="value-input source-waveform-field" data-source-param="offset" value="${sine.offset}" inputmode="decimal"/></label><label><span>Amplitude V</span><input class="value-input source-waveform-field" data-source-value="true" value="${sine.amplitude}" inputmode="decimal"/></label><label><span>Frequency Hz</span><input class="value-input source-waveform-field" data-source-param="frequency" value="${sine.frequency}" inputmode="decimal"/></label></div></div>`;}return"";}
function sweepSources():CircuitComponent[]{return circuit.components.filter(isIndependentSource).sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}));}
