function sweepOptions(selectedSourceId:string,excludeSourceId?:string):string{return sweepSources().filter(source=>source.id!==excludeSourceId).map(source=>`<option value="${esc(source.id)}" ${source.id===selectedSourceId?"selected":""}>${esc(sweepSourceLabel(source))}</option>`).join("");}
function activeDCSweepConfig():DCSweepConfig|undefined{return circuit.sim.dcSweep??defaultDCSweepConfig(circuit);}
function dcSweepRunSpec(config:DCSweepConfig):DCSweepRunSpec{const sourceById=(id:string)=>{const source=circuit.components.find(component=>component.id===id);if(!source||!isIndependentSource(source))throw new Error("Choose an independent voltage or current source");return source;};const primary=sourceById(config.sourceId);const make=(source:CircuitComponent,range:{start:number;stop:number;step:number})=>({componentId:source.id,name:dcSweepSourceName(source),unit:dcSweepSourceUnit(source),start:range.start,stop:range.stop,step:range.step});return{primary:make(primary,config),...(config.secondary?{secondary:make(sourceById(config.secondary.sourceId),config.secondary)}:{})};}
function dcSweepMarkup():string{const sources=sweepSources(),config=activeDCSweepConfig();if(!config||sources.length===0)return`<section class="inspector-section dc-sweep-panel" data-testid="dc-sweep-panel"><span class="field-label">DC SWEEP</span><p class="dc-sweep-error" role="alert">Add an independent voltage or current source to run a DC sweep.</p></section>`;const secondary=config.secondary,secondaryDefault=sources.find(source=>source.id!==config.sourceId);return`<section class="inspector-section dc-sweep-panel" data-testid="dc-sweep-panel"><span class="field-label">DC SWEEP</span><label class="field-label" for="dc-primary-source">Sweep source</label><select class="value-input dc-sweep-field" id="dc-primary-source">${sweepOptions(config.sourceId)}</select><div class="dc-sweep-grid"><label><span>Start</span><input class="value-input dc-sweep-field" id="dc-primary-start" value="${config.start}" inputmode="decimal"/></label><label><span>Stop</span><input class="value-input dc-sweep-field" id="dc-primary-stop" value="${config.stop}" inputmode="decimal"/></label><label><span>Step</span><input class="value-input dc-sweep-field" id="dc-primary-step" value="${config.step}" inputmode="decimal"/></label></div><label class="switch-row"><input id="dc-secondary-enabled" type="checkbox" ${secondary?"checked":""} ${sources.length<2?"disabled":""}/> Step a second source</label><div class="dc-secondary-fields" ${secondary?"":"hidden"}><label class="field-label" for="dc-secondary-source">Secondary source</label><select class="value-input dc-sweep-field" id="dc-secondary-source">${sweepOptions(secondary?.sourceId??secondaryDefault?.id??"")}</select><div class="dc-sweep-grid"><label><span>Start</span><input class="value-input dc-sweep-field" id="dc-secondary-start" value="${secondary?.start??0}" inputmode="decimal"/></label><label><span>Stop</span><input class="value-input dc-sweep-field" id="dc-secondary-stop" value="${secondary?.stop??1}" inputmode="decimal"/></label><label><span>Step</span><input class="value-input dc-sweep-field" id="dc-secondary-step" value="${secondary?.step??.1}" inputmode="decimal"/></label></div></div><p class="honesty-note">Linear sweep. Maximum ${DC_SWEEP_MAX_POINTS.toLocaleString()} total points.</p><p class="dc-sweep-error" id="dc-sweep-error" role="alert" hidden></p><button class="primary-button dc-run-button" id="run-dc-sweep">Run sweep</button></section>`;}
function noiseProbes():CircuitProbe[]{return circuit.probes.filter(probe=>probe.expression.kind==="voltage");}
