function noiseMarkup():string{const probes=noiseProbes(),sources=sweepSources(),config=activeNoiseConfig();if(probes.length===0)return`<section class="inspector-section noise-panel" data-testid="noise-panel"><span class="field-label">NOISE</span><p class="noise-error" role="alert">Add a voltage probe to choose the output noise measurement.</p></section>`;if(sources.length===0||!config)return`<section class="inspector-section noise-panel" data-testid="noise-panel"><span class="field-label">NOISE</span><p class="noise-error" role="alert">Add an independent voltage or current source to define the input reference.</p></section>`;return`<section class="inspector-section noise-panel" data-testid="noise-panel"><span class="field-label">NOISE</span><label class="field-label" for="noise-output-probe">Output measurement</label><select class="value-input noise-field" id="noise-output-probe">${noiseProbeOptions(config.outputProbeId)}</select><label class="field-label noise-label" for="noise-input-source">Input reference source</label><select class="value-input noise-field" id="noise-input-source">${sweepOptions(config.inputSourceId)}</select><div class="noise-grid"><label><span>Start Hz</span><input class="value-input noise-field" id="noise-start" value="${config.fstart}" inputmode="decimal"/></label><label><span>Stop Hz</span><input class="value-input noise-field" id="noise-stop" value="${config.fstop}" inputmode="decimal"/></label><label><span>Points / decade</span><input class="value-input noise-field" id="noise-points" value="${config.pointsPerDecade}" inputmode="numeric"/></label><label><span>Temperature °C</span><input class="value-input noise-field" id="noise-temperature" value="${config.temperatureC}" inputmode="decimal"/></label></div><p class="honesty-note">Small-signal noise is linearized at the DC operating point. The output is the selected voltage probe relative to ground.</p><p class="honesty-note">Resistors and noise-enabled device models contribute thermal or flicker noise. Ideal independent sources are noiseless. The selected source is forced to AC 1 only as a gain reference.</p><p class="honesty-note">Input-referred noise means output noise divided by the small-signal gain from the selected source at the configured temperature.</p><p class="noise-error" id="noise-error" role="alert" hidden></p><button class="primary-button noise-run-button" id="run-noise">Run noise</button></section>`;}
function catalogFor(component:CircuitComponent):CatalogPart|undefined{const catalogId=typeof component.params?.catalogPartId==="string"?component.params.catalogPartId:undefined,reference=catalogId??component.mpn;if(!reference||typeof component.params?.importedPartId==="string")return undefined;const catalog=catalogModule?.catalogPart(reference);if(!catalog&&!catalogModule)void loadCatalog().then(()=>{if(selectedId===component.id)renderInspector();}).catch(error=>setStatus(error instanceof Error?error.message:String(error),"error"));return catalog;}
function renderInspector(){const component=selected();if(!component){inspector.innerHTML=`<section class="inspector-section"><span class="field-label">NO SELECTION</span><p>Select a part to edit its properties.</p></section>${simConfigMarkup()}`;bindInspector();return;}const info=detail(component),catalog=catalogFor(component),current=componentCurrent(component),value=component.value??"";const editable=component.type!=="ground"&&component.type!=="opamp_ideal"&&component.type!=="bjt_npn"&&component.type!=="bjt_pnp"&&component.type!=="nmos"&&component.type!=="pmos",valueEditor=component.type!=="vsource_pulse"&&component.type!=="vsource_sine";const pins=(generated?.componentNodes[component.id]??componentPinCount(component)).map((_,index)=>`<div class="measure-row" data-reading-pin="${index}"><span class="measure-label">Pin ${index+1} V</span>${readingMarkup(pinVoltage(component.id,index),"V")}</div>`).join("");inspector.innerHTML=`<section class="inspector-section"><div class="part-heading"><span class="part-ref">${esc(info.ref)}</span>${typeof component.params?.importedPartId==="string"?`<span class="unverified-tag">imported, unverified</span>`:catalog?`<span class="fidelity">${esc(catalog.manifest.fidelity_tier)}</span>`:`<span class="generic-tag">generic</span>`}</div><div class="part-name">${esc(catalog?.manifest.description??info.name)}<br>${esc(info.identity)}</div>${catalog?`<p class="honesty-note">${esc(catalog.manifest.supported_operating_region?.summary??"Reviewed package model bundled with this build.")}</p><button class="model-card-link" data-inspector-model-card="${esc(catalog.id)}">Open model card</button>`:info.note?`<p class="honesty-note">${esc(info.note)}</p>`:""}</section>${editable?`<section class="inspector-section">${valueEditor?`<label class="field-label" for="component-value">${valueLabel(component)}</label><input class="value-input" id="component-value" value="${esc(String(value))}" inputmode="decimal"/><p class="honesty-note">Engineering suffixes accepted: 10k, 4.7u, 2m.</p>`:""}${sourceWaveformMarkup(component)}${component.type==="potentiometer"?`<label class="field-label wiper-label" for="wiper-value">Wiper position</label><input class="value-input" id="wiper-value" type="range" min="0.005" max="0.995" step="0.001" value="${Number(component.params?.t??.5)}"/><output id="wiper-percent">${Math.round(Number(component.params?.t??.5)*100)} %</output><div class="wiper-inline" id="wiper-inline">${readingMarkup(typeof component.value==="number"?component.value:parseEngineering(String(component.value??0),0),"Ω")}<span> · wiper ${Number(component.params?.t??.5).toFixed(2)}</span></div>`:""}${component.type==="switch_spst"?`<label class="switch-row"><input id="switch-state" type="checkbox" ${component.params?.closed?"checked":""}/> Closed</label>`:""}</section>`:""}<section class="inspector-section"><span class="field-label">LIVE MEASUREMENTS</span>${pins}<div class="measure-row" data-reading-current><span class="measure-label">Branch I</span>${readingMarkup(current,"A","branch-current")}</div></section>${simConfigMarkup()}`;bindInspector();}
function patchReadings(){const component=selected();if(!component)return;inspector.querySelectorAll<HTMLElement>("[data-reading-pin]").forEach(row=>{const index=Number(row.dataset.readingPin);row.querySelector(".reading")?.remove();row.insertAdjacentHTML("beforeend",readingMarkup(pinVoltage(component.id,index),"V"));});const currentRow=inspector.querySelector<HTMLElement>("[data-reading-current]");if(currentRow){currentRow.querySelector(".reading")?.remove();currentRow.insertAdjacentHTML("beforeend",readingMarkup(componentCurrent(component),"A","branch-current"));}const t=Number(component.params?.t??.5);const percent=inspector.querySelector<HTMLOutputElement>("#wiper-percent");if(percent)percent.textContent=`${Math.round(t*100)} %`;const inline=inspector.querySelector<HTMLElement>("#wiper-inline");if(inline){const resistance=typeof component.value==="number"?component.value:parseEngineering(String(component.value??0),0);inline.innerHTML=`${readingMarkup(resistance,"Ω")}<span> · wiper ${t.toFixed(2)}</span>`;}}
